# The documentation site: docs\*.md -> site\docs\**.html, generated by src\tools\docsite. This script builds the
# generator if needed, runs it, then checks that every internal link and anchor in the generated pages resolves (zero
# dead links, zero dead anchors). The generation is deterministic (same docs, _nav.txt and git history -> same bytes),
# so -Check verifies site\docs is up to date without writing, the way tools\changelog.ps1 -Check does.
#
#   powershell -File tools\docs_site.ps1            build docsite if needed, regenerate site\docs, then check links
#   powershell -File tools\docs_site.ps1 -Check     write nothing; fail if site\docs is stale or any link/anchor is dead (CI)
#   powershell -File tools\docs_site.ps1 -NoBuild   skip rebuilding docsite.exe (use the existing one)
#
# Exit code 0 when all is well, 1 otherwise.
param(
    [switch]$Check,
    [switch]$NoBuild
)
$ErrorActionPreference = 'Stop'
$Root = Split-Path $PSScriptRoot -Parent
Push-Location $Root
try {
    $exe = Join-Path $Root 'build\docsite.exe'

    # Build the generator unless asked not to, or when it is missing or older than its sources.
    if (-not $NoBuild) {
        $need = -not (Test-Path $exe)
        if (-not $need) {
            $built = (Get-Item $exe).LastWriteTimeUtc
            $need = @(Get-ChildItem 'src\tools\docsite' -Filter *.odin | Where-Object { $_.LastWriteTimeUtc -gt $built }).Count -gt 0
        }
        if ($need) {
            New-Item -ItemType Directory -Force (Join-Path $Root 'build') | Out-Null
            cmd /c "odin build src/tools/docsite -collection:wb=src -vet -out:build/docsite.exe 2>&1" | Out-Host
            if ($LASTEXITCODE) { Write-Error 'docs_site: docsite did not build'; exit 1 }
        }
    }
    if (-not (Test-Path $exe)) { Write-Error 'docs_site: build\docsite.exe is missing (run without -NoBuild)'; exit 1 }

    # Generate (or verify the output is current).
    $arg = if ($Check) { '-check' } else { '' }
    & $exe $arg
    if ($LASTEXITCODE) {
        if ($Check) { Write-Error 'docs_site: site\docs is out of date (run tools\docs_site.ps1)' }
        else { Write-Error 'docs_site: generation failed' }
        exit 1
    }

    # Link check: read every generated page, collect the ids it defines and the internal links it uses, then verify
    # each link points at a page that exists and (for a #fragment) an id that page defines.
    $outDir = Join-Path $Root 'site\docs'
    $pages = Get-ChildItem $outDir -Recurse -Filter *.html
    $idsByUrl = @{}   # "/docs/x.html" -> set of ids
    $texts = @{}      # path -> content
    foreach ($p in $pages) {
        $text = [IO.File]::ReadAllText($p.FullName)
        $texts[$p.FullName] = $text
        $url = '/docs/' + ($p.FullName.Substring($outDir.Length + 1) -replace '\\', '/')
        $ids = New-Object System.Collections.Generic.HashSet[string]
        foreach ($m in [regex]::Matches($text, 'id="([^"]+)"')) { [void]$ids.Add($m.Groups[1].Value) }
        $idsByUrl[$url] = $ids
    }

    $dead = @()
    foreach ($p in $pages) {
        $text = $texts[$p.FullName]
        foreach ($m in [regex]::Matches($text, 'href="(/docs/[^"#]*)(#[^"]*)?"')) {
            $target = $m.Groups[1].Value
            $frag = $m.Groups[2].Value
            if ($target -notmatch '\.(html|css|js|json|svg|png|webp|gif|jpg|jpeg)$') { continue }
            if ($target -match '\.html$') {
                if (-not $idsByUrl.ContainsKey($target)) {
                    $dead += "{0}: link to missing page {1}" -f $p.Name, $target
                    continue
                }
                if ($frag) {
                    $id = $frag.Substring(1)
                    if ($id -and -not $idsByUrl[$target].Contains($id)) {
                        $dead += "{0}: link to missing anchor {1}{2}" -f $p.Name, $target, $frag
                    }
                }
            } else {
                # a non-page asset under /docs/ (the generated css/js/json/svg): it must exist on disk
                $rel = $target.Substring('/docs/'.Length) -replace '/', '\'
                if (-not (Test-Path (Join-Path $outDir $rel))) {
                    $dead += "{0}: link to missing asset {1}" -f $p.Name, $target
                }
            }
        }
        # same-page #fragments must exist on this page
        foreach ($m in [regex]::Matches($text, 'href="(#[^"]+)"')) {
            $id = $m.Groups[1].Value.Substring(1)
            if ($id -and -not $idsByUrl['/docs/' + ($p.FullName.Substring($outDir.Length + 1) -replace '\\', '/')].Contains($id)) {
                $dead += "{0}: link to missing anchor {1}" -f $p.Name, $m.Groups[1].Value
            }
        }
    }

    if ($dead.Count) {
        Write-Host ("docs_site: {0} dead internal link(s)/anchor(s):" -f $dead.Count)
        $dead | Sort-Object -Unique | ForEach-Object { Write-Host "  $_" }
        exit 1
    }
    Write-Host ("docs_site: {0} pages, every internal link and anchor resolves" -f $pages.Count)
    exit 0
}
finally {
    Pop-Location
}
